import os from 'node:os';
import path from 'node:path';
import { restore } from './src/restore.js';

const results = [];
async function expect(name, fn, code) {
  try { const r = await fn(); results.push(`${code ? 'FAIL' : 'ok  '} ${name} -> ${JSON.stringify(r)}`); }
  catch (e) { results.push(`${e.code === code ? 'ok  ' : 'FAIL'} ${name} -> ${e.code}`); }
}
const ws = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-smoke-'));
const outside = await fs.mkdtemp(path.join(os.tmpdir(), 'restore-outside-'));
await fs.writeFile(path.join(outside, 'secret.txt'), 'outside');
await fs.writeFile(path.join(ws, '.hidden'), 'h');
await fs.mkdir(path.join(ws, 'docs'));
await fs.writeFile(path.join(ws, 'docs/a.txt'), 'a');
await fs.writeFile(path.join(ws, 'old.txt'), 'old');
await fs.symlink(outside, path.join(ws, 'link'), 'junction');

const W = (p, c = 'x') => ({ path: p, content: c });
const g = (p, operation) => ({ path: p, operation });

await expect('extra field approved', () => restore(ws, { writes: [], deletes: [], approved: true }, []), 'ERR_INVALID_MANIFEST');
await expect('extra write field', () => restore(ws, { writes: [{ ...W('a.txt'), replace: true }], deletes: [] }, [g('a.txt', 'write')]), 'ERR_INVALID_MANIFEST');
await expect('non-string content', () => restore(ws, { writes: [{ path: 'a.txt', content: 1 }], deletes: [] }, []), 'ERR_INVALID_MANIFEST');
await expect('null manifest', () => restore(ws, null, []), 'ERR_INVALID_MANIFEST');
await expect('empty ok', () => restore(ws, { writes: [], deletes: [] }, []));
for (const p of ['/abs.txt', '../x', './x', 'a//b', 'a\\b', 'c:x', 'CON', 'con', 'nul.txt', 'com1.tar.gz', 'lpt9', 'Upper.txt', 'a/', '.hidden', 'a..b']) {
