await expect('bad grant path', () => restore(ws, { writes: [], deletes: [] }, [g('../a', 'write')]), 'ERR_INVALID_GRANT');
await expect('grants not array', () => restore(ws, { writes: [], deletes: [] }, null), 'ERR_INVALID_GRANT');
