await expect('wrong op denied', () => restore(ws, { writes: [], deletes: ['old.txt'] }, [g('old.txt', 'write')]), 'ERR_DENIED');
await expect('partial deny, no mutation', () => restore(ws, { writes: [W('fresh/new.txt'), W('other.txt')], deletes: [] }, [g('fresh/new.txt', 'write')]), 'ERR_DENIED');
await expect('junction ancestor', () => restore(ws, { writes: [W('link/secret.txt', 'pwn')], deletes: [] }, [g('link/secret.txt', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('junction delete', () => restore(ws, { writes: [], deletes: ['link'] }, [g('link', 'delete')]), 'ERR_UNSAFE_TARGET');
