await expect('file ancestor', () => restore(ws, { writes: [W('old.txt/x')], deletes: [] }, [g('old.txt/x', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('unsafe after valid, no mutation', () => restore(ws, { writes: [W('fresh2/a.txt'), W('docs')], deletes: [] }, [g('fresh2/a.txt', 'write'), g('docs', 'write')]), 'ERR_UNSAFE_TARGET');
await expect('root junction', () => restore(path.join(ws, 'link'), { writes: [], deletes: [] }, []), 'ERR_UNSAFE_TARGET');
await expect('success', () => restore(ws, { writes: [W('docs/a.txt', 'new'), W('n/m.txt', 'nm')], deletes: ['missing.txt', 'old.txt'] },
  [g('docs/a.txt', 'write'), g('docs/a.txt', 'write'), g('n/m.txt', 'write'), g('old.txt', 'delete'), g('missing.txt', 'delete')]));

const exists = async p => fs.access(p).then(() => true, () => false);
results.push(`fresh absent: ${!(await exists(path.join(ws, 'fresh')))}, fresh2 absent: ${!(await exists(path.join(ws, 'fresh2')))}, other absent: ${!(await exists(path.join(ws, 'other.txt')))}`);
